readOnlyQueries.database:
\pset pager off
\timing on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='60s';
SELECT now() AS sampled_at, pg_size_pretty(pg_database_size(current_database())) AS database_size, version();
SELECT datname,pg_size_pretty(pg_database_size(oid)) AS size FROM pg_database ORDER BY pg_database_size(oid) DESC;
SELECT relname,pg_size_pretty(pg_total_relation_size(relid)) AS total,n_live_tup,n_dead_tup,last_autovacuum,last_autoanalyze FROM pg_stat_user_tables ORDER BY pg_total_relation_size(relid) DESC LIMIT 15;
SELECT count(*) FILTER (WHERE wait_event_type='Lock') AS lock_waiters,count(*) FILTER (WHERE state='idle in transaction') AS idle_in_transaction,max(now()-xact_start) FILTER (WHERE pid<>pg_backend_pid()) AS oldest_other_transaction FROM pg_stat_activity WHERE datname=current_database();
SELECT count(*) FILTER (WHERE NOT indisvalid) AS invalid_indexes,count(*) FILTER (WHERE NOT indisready) AS not_ready_indexes FROM pg_index WHERE indrelid IN (SELECT oid FROM pg_class WHERE relnamespace='proof_indexer'::regnamespace);
SELECT count(*) AS unvalidated_constraints FROM pg_constraint WHERE connamespace='proof_indexer'::regnamespace AND NOT convalidated;
SELECT slot_name,slot_type,active,pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(),restart_lsn)) AS retained FROM pg_replication_slots;
SELECT datname,deadlocks,checksum_failures,temp_bytes,stats_reset FROM pg_stat_database WHERE datname=current_database();
SELECT protocol,kind,status,valid,count(*) AS rows FROM proof_indexer.events GROUP BY protocol,kind,status,valid ORDER BY protocol,kind,status,valid;
SELECT count(*) FILTER(WHERE confirmed_balance<0) AS negative_balances,count(*) FILTER(WHERE confirmed_balance<>trunc(confirmed_balance)) AS fractional_storage,count(*) FILTER(WHERE pending_delta<>0) AS nonzero_pending_deltas,count(*) AS balance_rows,count(DISTINCT address) AS balance_addresses FROM proof_indexer.credit_balances;
SELECT d.ticker,d.token_id,d.max_supply::text,sum(b.confirmed_balance)::text AS confirmed_supply,sum(b.pending_delta)::text AS pending_delta,count(*) FILTER(WHERE b.confirmed_balance>0) AS holders FROM proof_indexer.credit_definitions d JOIN proof_indexer.credit_balances b USING(network,token_id) GROUP BY d.network,d.token_id,d.ticker,d.max_supply HAVING d.ticker IN ('WORK','POWB','INCB') OR (d.max_supply>0 AND sum(b.confirmed_balance)>d.max_supply) ORDER BY ticker;
SELECT e.txid,e.kind,e.valid,e.status,e.block_height,e.payload->>'amount' AS amount,e.payload->>'reasonCode' AS reason FROM proof_indexer.events e WHERE e.payload->>'tokenId'='d4e5ebf11d104d6a63fb74e42094364b25a5f7199a09e5c0e71408972466a8b8' AND (e.payload ? 'amount') AND NOT(e.payload ? 'amountAtoms') AND NOT(e.payload ? 'amountSubatoms') ORDER BY e.block_height,e.event_id;
WITH ordered AS (SELECT *,lag(block_height) OVER(ORDER BY block_height) AS prev_height,lag(block_hash) OVER(ORDER BY block_height) AS prev_hash,lag(closing_network_value_q8) OVER(ORDER BY block_height) AS prev_value FROM proof_indexer.work_amo_block_transitions WHERE network='livenet') SELECT min(block_height),max(block_height),count(*),count(*) FILTER(WHERE prev_height IS NOT NULL AND block_height<>prev_height+1) AS height_gaps,count(*) FILTER(WHERE prev_hash IS NOT NULL AND previous_block_hash<>prev_hash) AS hash_gaps,count(*) FILTER(WHERE prev_value IS NOT NULL AND opening_network_value_q8<>prev_value) AS value_gaps,count(*) FILTER(WHERE NOT complete OR NOT fee_once OR NOT invalid_zero OR NOT block_atomic) AS invalid_flags FROM ordered;
SELECT count(*) AS confirmed_missing_inputs FROM proof_indexer.transactions t WHERE status='confirmed' AND NOT EXISTS(SELECT 1 FROM proof_indexer.tx_inputs i WHERE i.network=t.network AND i.txid=t.txid);
SELECT count(*) AS confirmed_missing_outputs FROM proof_indexer.transactions t WHERE status='confirmed' AND NOT EXISTS(SELECT 1 FROM proof_indexer.tx_outputs o WHERE o.network=t.network AND o.txid=t.txid);
SELECT count(*) AS confirmed_event_parent_position_mismatch FROM proof_indexer.events e JOIN proof_indexer.transactions t USING(network,txid) WHERE e.status='confirmed' AND (t.status<>'confirmed' OR e.block_height IS DISTINCT FROM t.block_height OR e.block_index IS DISTINCT FROM t.block_index);
SELECT key,updated_at FROM proof_indexer.meta WHERE key ILIKE '%migration%' OR key ILIKE '%pending%' OR key ILIKE '%workPrecision%' ORDER BY key;
COMMIT;

readOnlyQueries.detailIntegrity:
\pset pager off
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='45s';
SHOW data_checksums;
WITH ins AS(SELECT network,txid,count(*) n,count(value_sats) valued,sum(value_sats) total FROM proof_indexer.tx_inputs GROUP BY network,txid),outs AS(SELECT network,txid,count(*) n,sum(value_sats) total FROM proof_indexer.tx_outputs GROUP BY network,txid),detail AS(SELECT t.*,ins.n inputs,ins.valued,ins.total input_sum,outs.n outputs,outs.total output_sum FROM proof_indexer.transactions t LEFT JOIN ins USING(network,txid) LEFT JOIN outs USING(network,txid) WHERE status='confirmed') SELECT count(*) total,count(*) FILTER(WHERE coalesce(inputs,0)<>jsonb_array_length(raw_tx->'vin')) input_count_mismatch,count(*) FILTER(WHERE coalesce(outputs,0)<>jsonb_array_length(raw_tx->'vout')) output_count_mismatch,count(*) FILTER(WHERE inputs<>valued) incomplete_input_values,count(*) FILTER(WHERE fee_sats IS NULL) absent_fee,count(*) FILTER(WHERE inputs=valued AND outputs>0 AND input_sum-output_sum<>fee_sats) fee_mismatch,count(*) FILTER(WHERE inputs=valued AND outputs>0 AND input_sum<output_sum) negative_fee FROM detail;
SELECT count(*) AS wrong_spend_links FROM proof_indexer.tx_outputs o WHERE spent_by_txid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM proof_indexer.tx_inputs i WHERE i.network=o.network AND i.txid=o.spent_by_txid AND i.prev_txid=o.txid AND i.prev_vout=o.vout AND i.vin=o.spent_by_vin);
SELECT count(*) AS event_missing_raw_carrier FROM proof_indexer.events e WHERE status='confirmed' AND NOT EXISTS(SELECT 1 FROM proof_indexer.op_returns o WHERE o.network=e.network AND o.txid=e.txid AND o.vout=e.op_return_vout);
COMMIT;
